module apbslave #(
    parameter C_APB_ADDR_WIDTH = 12,
    parameter C_APB_DATA_WIDTH = 32,
    localparam AW = C_APB_ADDR_WIDTH,
    localparam DW = C_APB_DATA_WIDTH,
    localparam APBLSB = $clog2(C_APB_DATA_WIDTH)-3
) (
    input wire            PCLK, PRESETn,
    input wire            PSEL,
    input wire            PENABLE,
    output reg            PREADY,
    input wire    [AW-1:0] PADDR,
    input wire            PWRITE,
    input wire    [DW-1:0] PWDATA,
    input wire    [DW/8-1:0] PWSTRB,
    input wire    [2:0]     PPROT,
    output reg    [DW-1:0] PRDATA,
    output wire           PSLVERR
);

reg [DW-1:0] data_reg;
reg [AW-1:0] addr_reg;
reg         write_reg;
reg         enable_reg;
reg         ready_reg;
reg         error_reg;

always @(posedge PCLK or negedge PRESETn) begin
    if (~PRESETn) begin
        PREADY <= 1'b0;
        PRDATA <= {DW{1'b0}};
        PSLVERR <= 1'b0;
        data_reg <= {DW{1'b0}};
        addr_reg <= {AW{1'b0}};
        write_reg <= 1'b0;
        enable_reg <= 1'b0;
        ready_reg <= 1'b0;
        error_reg <= 1'b0;
    end else begin
        if (PSEL && PENABLE) begin
            if (PWRITE) begin
                // Write operation
                for (int i = 0; i < DW/8; i++) begin
                    if (PWSTRB[i]) begin
                        data_reg[(i*8)+:8] <= PWDATA[(i*8)+:8];
                    end
                end
            end else begin
                // Read operation
                PRDATA <= data_reg;
            end
            ready_reg <= 1'b1;
        end else if (PSEL && ~PENABLE) begin
            // Setup phase
            addr_reg <= PADDR;
            write_reg <= PWRITE;
            enable_reg <= 1'b1;
        end else begin
            // Idle state
            ready_reg <= 1'b0;
            enable_reg <= 1'b0;
        end
        if (ready_reg) begin
            PREADY <= 1'b1;
        end else begin
            PREADY <= 1'b0;
        end
        if (PADDR[AW-1:APBLSB]!= {AW-APBLSB{1'b0}}) begin
            error_reg <= 1'b1;
        end else begin
            error_reg <= 1'b0;
        end
        if (error_reg) begin
            PSLVERR <= 1'b1;
        end else begin
            PSLVERR <= 1'b0;
        end
    end
end

endmodule
